const raw = $input.item.json;
const d = (raw['0'] && typeof raw['0'] === 'object') ? raw['0'] : raw;
const tipo = (d.TIPO || '').toString().trim();

// ── Categorias de eventos ─────────────────────────────────────────────────────
// Alertas que vão para AMBAS as sheets (SUPORTE + CLIENTE)
const alertasAmbos = [
  'ALERTA_TEMP_ALTA', 'ALERTA_TEMP_BAIXA', 'TEMP_NORMALIZADA',
  'ALERTA_TENSAO_ALTA', 'ALERTA_TENSAO_BAIXA'
];
// Alertas que vão APENAS para SUPORTE
const alertasSoSuporte = [
  'ALERTA_FALTA_ENERGIA', 'ENERGIA_RESTABELECIDA',
  'ALERTA_BATERIA_BAIXA', 'BATERIA_NORMALIZADA',
  'ALERTA_PORTA_ABERTA', 'PORTA_FECHADA'
];

const tipoValido = tipo === 'relatorio_diario'
  || tipo === 'periodico_suporte'
  || alertasAmbos.includes(tipo)
  || alertasSoSuporte.includes(tipo);

if (!tipoValido) return [];

// ── Campos normalizados ───────────────────────────────────────────────────────
const temp     = d.TEMP_ATUAL || d.temperatura || d.TEMP || '';
const voltagem = d.VOLTAGEM   || d.voltagem    || '';
const bateria  = d.BATERIA    || d.bateria     || '';
const hora     = d.HORA       || d.hora        || '';
const data_    = d.DATA       || d.data        || '';
const disp     = d.DISPOSITIVO|| d.dispositivo || '';
const maxV     = d.MAX        || d.max         || '';
const minV     = d.MIN        || d.min         || '';
const alarmMax = d.ALARM_MAX  || '?';
const alarmMin = d.ALARM_MIN  || '?';
const voltMax  = d.VOLT_MAX_LIMIT || '?';
const voltMin  = d.VOLT_MIN_LIMIT || '?';
const batMin   = d.BAT_MIN_LIMIT  || '?';

// ── Observação descritiva do evento ──────────────────────────────────────────
const obsMap = {
  'relatorio_diario':      'Relatório automático',
  'periodico_suporte':     'Monitoramento horário',
  'ALERTA_TEMP_ALTA':      `⚠️ Temperatura ALTA ${temp}°C (limite: ${alarmMax}°C)`,
  'ALERTA_TEMP_BAIXA':     `⚠️ Temperatura BAIXA ${temp}°C (limite: ${alarmMin}°C)`,
  'TEMP_NORMALIZADA':      `✅ Temperatura normalizada ${temp}°C`,
  'ALERTA_TENSAO_ALTA':    `⚡ Tensão ALTA ${voltagem}V (limite: ${voltMax}V)`,
  'ALERTA_TENSAO_BAIXA':   `⚡ Tensão BAIXA ${voltagem}V (limite: ${voltMin}V)`,
  'ALERTA_FALTA_ENERGIA':  '🔌 Falta de energia detectada',
  'ENERGIA_RESTABELECIDA': '✅ Energia restabelecida',
  'ALERTA_BATERIA_BAIXA':  `🪫 Bateria baixa ${bateria}V (limite: ${batMin}V)`,
  'BATERIA_NORMALIZADA':   `✅ Bateria normalizada ${bateria}V`,
  'ALERTA_PORTA_ABERTA':   '🚪 Porta aberta detectada',
  'PORTA_FECHADA':         '✅ Porta fechada',
};
const obs = obsMap[tipo] || tipo;

// ── Linha para sheet SUPORTE (dados completos de todos os sensores) ───────────
const linhaSuporte = {
  _destino_sheet: 'SUPORTE',
  HORA: hora, DATA: data_, DISPOSITIVO: disp, TIPO: tipo,
  TEMP: temp, TEMP_AMBIENTE: d.TEMP_EXTERNA || '',
  MAX: maxV, MIN: minV,
  VOLTAGEM: voltagem, BATERIA: bateria,
  OBS: obs
};

// ── Linha para sheet CLIENTE (dados de temperatura e limites) ─────────────────
const linhaCliente = {
  _destino_sheet: 'CLIENTE',
  HORA: hora, DATA: data_, DISPOSITIVO: disp,
  TEMP: temp, MAX: maxV, MIN: minV, OBS: obs
};

// ── Roteamento ────────────────────────────────────────────────────────────────

// periodico_suporte → apenas SUPORTE (todos os dados horários)
if (tipo === 'periodico_suporte') {
  return [{ json: linhaSuporte }];
}

// relatorio_diario (8h e 16h) → apenas CLIENTE
if (tipo === 'relatorio_diario') {
  return [{ json: linhaCliente }];
}

// Alertas de temp/tensão → SUPORTE + CLIENTE
if (alertasAmbos.includes(tipo)) {
  return [
    { json: linhaSuporte },
    { json: linhaCliente }
  ];
}

// Demais alertas (energia, bateria, porta) → apenas SUPORTE
return [{ json: linhaSuporte }];

const d = $json;
const remoteJid = d.REMOTE_JID || '';
const tipo = (d.TIPO || '').toString();

// Build WhatsApp-formatted message from mapped Edit Fields data
let msg = '';

if (tipo === 'STATUS_SOLICITADO') {
  const temp    = d.temperatura || d.TEMP || d.TEMP_C || '?';
  const max     = d.MAX || d.TEMP_MAX || '?';
  const min     = d.MIN || d.TEMP_MIN || '?';
  const volt    = d.VOLTAGEM || '';
  const bat     = d.BATERIA || '';
  const hora    = d.hora || '';
  const dataStr = d.data || '';
  const device  = d.deviceName || d.device || d.DISPOSITIVO || 'Sensor';
  const rssi    = d.RSSI || '';
  const modo    = d.MODO || '';
  const rele    = d.RELE;
  const alMax   = d.ALARM_MAX || '';
  const alMin   = d.ALARM_MIN || '';

  msg  = `🌡️ *Status do Dispositivo*\n`;
  msg += `📱 *${device}*\n`;
  msg += `📅 ${dataStr}  🕰️ ${hora}\n\n`;
  msg += `🌡️ Temperatura: *${temp}°C*\n`;
  msg += `📊 Hoje — Min: ${min}°C / Max: ${max}°C\n\n`;

  if (volt && parseFloat(volt) > 0.1) msg += `⚡ Tensão: *${volt}V*\n`;
  if (bat)  msg += `🔋 Bateria: *${bat}V*\n`;
  if (rele !== '' && rele !== undefined) msg += `💡 Relé: *${rele ? 'LIGADO' : 'DESLIGADO'}*\n`;
  if (modo) msg += `⚙️ Modo: *${modo}*\n`;
  if (rssi) msg += `📶 Sinal WiFi: *${rssi} dBm*\n`;

} else if (tipo === 'DADOS_AMBIENTE') {
  msg = d.msg || `🌍 *Dados Ambientais*\n📅 ${d.data || ''} às ${d.hora || ''}`;
}

if (!msg) return [];

// If we have a specific REMOTE_JID, send directly to that person
if (remoteJid) {
  return [{ json: { _destino: 'DIRETO', remoteJid, msg } }];
}

// No REMOTE_JID (firmware not yet updated): broadcast to all registered users
// Pass to the next node which handles the numeros array
const numeros = d.numeros || d.numeross || [];
return numeros.map(n => ({
  json: { _destino: 'BROADCAST_UNIT', remoteJid: n.phone, msg }
}));

const item = $input.first().json;
const tipo = (item.TIPO || '').toString();
const remoteJid = item.REMOTE_JID || item.REMOTE_jid || '';

// ─── Helpers ──────────────────────────────────────────────────────────────
const fmt = (v, unit='') => (v !== undefined && v !== null && v !== '') ? `${v}${unit}` : '?';

// ─── TIPOS DE TELEMETRIA PERMITIDOS ───────────────────────────────────────
const tiposTelemetriaPermitidos = [
  'ALERTA_TEMP_ALTA',
  'ALERTA_TEMP_BAIXA',
  'TEMP_NORMALIZADA',
  'ALERTA_TENSAO_ALTA',
  'TENSAO_NORMALIZADA',
  'ALERTA_TENSAO_BAIXA',
  'ALERTA_BATERIA_BAIXA',
  'BATERIA_NORMALIZADA',
  'ALERTA_FALTA_ENERGIA',
  'ENERGIA_RESTABELECIDA',
  'ALERTA_PORTA_ABERTA',
  'PORTA_FECHADA',
  'ALERTA_DISPOSITIVO_OFFLINE'
];

// ─── CATEGORY 1: COMANDO – preformatted static messages ───────────────────
const mensagensComando = {
  'MANUTENCAO_ATIVADA':     '🔧 *Modo Manutenção ativado!*\n\nTodos alertas e relatórios foram suspensos.\nO dispositivo está em manutenção.',
  'MANUTENCAO_DESATIVADA':  '✅ *Modo Operacional restaurado!*\n\nO sistema voltou ao monitoramento automático.',
  'EM_MANUTENCAO':          '⚠️ *Dispositivo em manutenção.*\n\nComandos bloqueados. Envie "operacional" para sair do modo manutenção.',
  'ALARME_SILENCIADO':      '🔕 *Alarme silenciado.*\n\nOs alertas persistentes foram suspensos até normalização.',
  'ERRO_NAO_AUTORIZADO':    '🚫 *Acesso negado.*\n\nVocê não tem permissão para executar este comando.',
  'feedback_comando':        '✅ *Comando executado com sucesso.*',
  'feedback_calibracao_sucesso':         '🗂️ *Calibração de tensão realizada com sucesso!*',
  'feedback_calibracao_bateria':         '🔋 *Calibração de bateria realizada com sucesso!*',
  'ALERTA_ERRO_CALIBRACAO_FATOR':        '❌ *Erro na calibração:* fator inválido.',
  'ALERTA_ERRO_CALIBRACAO_TENSAO_BAIXA': '❌ *Erro na calibração:* tensão lida muito baixa.',
};

// ─── feedback_configuracao ─── exibe APENAS o que foi alterado ───
if (tipo === 'feedback_configuracao') {
  const alarmMax = fmt(item.ALARM_MAX, '°C');
  const alarmMin = fmt(item.ALARM_MIN, '°C');
  const voltMax  = fmt(item.VOLT_MAX_LIMIT, 'V');
  const voltMin  = fmt(item.VOLT_MIN_LIMIT, 'V');
  const batMin   = fmt(item.BAT_MIN_LIMIT, 'V');
  const doorTime = fmt(item.DOOR_TIME, 's');
  const delayRele = fmt(item.VOLT_RETURN_DELAY, 's');

  const campos = (item.CAMPOS_ALTERADOS || '').split(',').filter(c => c);
  const mostrarTudo   = campos.length === 0;
  const alterouTemp   = mostrarTudo || campos.some(c => c === 'ALARM');
  const alterouTensao = mostrarTudo || campos.some(c => c === 'VOLT');
  const alterouBat    = mostrarTudo || campos.some(c => c === 'BAT');
  const alterouPorta  = mostrarTudo || campos.some(c => c === 'DOOR');

  let msg = '⚙️ *Configuração atualizada!*\n\n';
  if (alterouTemp)   msg += `🌡️ Temperatura: Mín ${alarmMin} / Máx ${alarmMax}\n`;
  if (alterouTensao && (voltMax !== '?V' || voltMin !== '?V')) msg += `⚡ Tensão: ${voltMin} – ${voltMax} (Atraso R3: ${delayRele})\n`;
  if (alterouBat    && batMin !== '?V')   msg += `🔋 Bateria mín: ${batMin}\n`;
  if (alterouPorta  && doorTime !== '?s') msg += `🚪 Porta máx: ${doorTime}\n`;

  return [{ json: { _tipo_resposta: 'COMANDO', remoteJid, msg } }];
}

const msgComando = mensagensComando[tipo];

// Static COMANDO: requires REMOTE_JID
if (msgComando && remoteJid) {
  return [{ json: {
    _tipo_resposta: 'COMANDO',
    remoteJid,
    msg: msgComando
  }}];
}

// ─── CATEGORY 2: SOLICITACAO – response to user data request ───────────────
const tiposSolicitacao = ['STATUS_SOLICITADO', 'DADOS_AMBIENTE'];
if (tiposSolicitacao.includes(tipo)) {
  return [{ json: { _tipo_resposta: 'SOLICITACAO', ...item }}];
}

// ─── CATEGORY 3: TELEMETRIA – apenas alertas permitidos ────────
if (tiposTelemetriaPermitidos.includes(tipo)) {
  const tenant = item.tenant_id || item.tenantId || '';
  const unlinked = ['Unknown', 'empresa_default', 'Nikaotec', 'unassigned', ''];
  if (unlinked.includes(tenant) || !tenant) {
    return []; // Descarta o alerta para dispositivos órfãos
  }
  return [{ json: { _tipo_resposta: 'TELEMETRIA', ...item }}];
}

// ─── Qualquer outro tipo: descartar (não propaga) ──────────────────────────
return [];

