const d = $json;
const tipo = d.TIPO || '';
const is_repeat = d.IS_REPEAT === true || String(d.IS_REPEAT).toLowerCase() === 'true';

const device = d.deviceName || d.device || d.DISPOSITIVO || 'N/A';
const dataStr = d.data || d.DATA || '';
const hora = d.hora || d.HORA || '';
const temp = d.temperatura || d.TEMP || '';
const max = d.MAX || 'N/A';
const min = d.MIN || 'N/A';
const volt = d.VOLTAGEM || 'N/A';
const bat = d.BATERIA || 'N/A';
const porta = d.PORTA || 'N/A';

const titulos = {
  'ALERTA_TEMP_ALTA': '🌡️🔴 Alerta: Temperatura Elevada',
  'ALERTA_TEMP_BAIXA': '🌡️🔵 Alerta: Temperatura Baixa',
  'TEMP_NORMALIZADA': '🌡️✅ Temperatura Normalizada',
  'ALERTA_TENSAO_ALTA': '⚡🔴 Alerta: Sobretensão Detectada',
  'ALERTA_TENSAO_BAIXA': '⚡🔵 Alerta: Subtensão Detectada',
  'TENSAO_NORMALIZADA': '⚡✅ Tensão Normalizada',
  'ALERTA_BATERIA_BAIXA': '🔋🪫 Alerta: Bateria Fraca',
  'BATERIA_NORMALIZADA': '🔋✅ Bateria Normalizada',
  'ALERTA_FALTA_ENERGIA': '🔌🔴 Alerta: Falta de Energia',
  'ENERGIA_RESTABELECIDA': '🔌✅ Energia Restabelecida',
  'ALERTA_PORTA_ABERTA': '🚪🔴 Alerta: Porta Aberta',
  'PORTA_FECHADA': '🚪✅ Porta Fechada',
  'ALERTA_DISPOSITIVO_OFFLINE': '⚠️🔴 Alerta: Dispositivo Offline'
};

let titulo = titulos[tipo] || `⚠️ ${tipo}`;

if (tipo === 'periodico_suporte' || tipo === 'relatorio_diario') {
  return [{ json: { output: '{"gestor": "IGNORAR", "outro": "IGNORAR"}' } }];
}

let gestor = `${titulo}\n\n📱 Dispositivo: ${device}\n📅 ${dataStr} às ${hora}\n\n`;

if (tipo === 'ALERTA_DISPOSITIVO_OFFLINE') {
    titulo = "⚠️🔴 DISPOSITIVO OFF-LINE ⚠️🔴";
    gestor += `🔴 O dispositivo não está enviando dados há mais de 2 minutos.\n\nFavor verificar a conexão com a internet ou fonte de alimentação.`;
} else if (tipo === 'ALERTA_DISPOSITIVO_ONLINE') {
    titulo = "🟢✅ DISPOSITIVO RECONECTADO 🟢✅";
    gestor += `✅ O dispositivo voltou a enviar dados e está operando normalmente.\n\nMonitoramento restabelecido.`;
} else if (tipo.includes('TEMP')) {
    gestor += `🌡️ Temperatura atual: ${temp}°C\n`;
    if (min !== 'N/A' && max !== 'N/A' && min !== '' && max !== '') {
        gestor += `📊 Limites: ${min}°C mín / ${max}°C máx\n`;
    }
} else if (tipo.includes('TENSAO') || tipo.includes('ENERGIA')) {
    if (volt !== 'N/A' && parseFloat(volt) > 0) gestor += `⚡ Tensão: ${volt}V\n`;
} else if (tipo.includes('BATERIA')) {
    if (bat !== 'N/A' && bat !== '') gestor += `🔋 Bateria: ${bat}V\n`;
} else if (tipo.includes('PORTA')) {
    if (porta !== 'N/A' && porta !== '') gestor += `🚪 Porta: ${porta}\n`;
} else {
    if (temp !== '') gestor += `🌡️ Temperatura atual: ${temp}°C\n`;
    if (volt !== 'N/A' && parseFloat(volt) > 0) gestor += `⚡ Tensão: ${volt}V\n`;
    if (bat !== 'N/A' && bat !== '') gestor += `🔋 Bateria: ${bat}V\n`;
}

if (is_repeat) gestor += `\n⚠️ Alerta persistente`;

let outro = gestor;
let parsed = { gestor, outro };

return [{ json: { output: JSON.stringify(parsed) } }];
